from pathlib import Path
import base64, hashlib, json, os, resource, signal, subprocess, time
from datetime import datetime, timezone
D=Path('/home/qian-qi/hepta-hcsn-core-study-20261110-c385-training/science-artifact-collection-launch-v1')
D.mkdir(exist_ok=False)
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()=='985d3427138f266c7810ec2500b840c968f23b16b06a276c886e575d652ad717'
src=D/'collect_native.py'; src.write_bytes(raw)
start=time.monotonic(); cpu0=resource.getrusage(resource.RUSAGE_CHILDREN)
report={'schema':'read-only-artifact-collection-outer-v1','stable_key':'hcsn-science-artifact-and-publication-collection-c385-v1','started_utc':datetime.now(timezone.utc).isoformat(),'source_sha256':'985d3427138f266c7810ec2500b840c968f23b16b06a276c886e575d652ad717','argv':['/usr/bin/python3','-B',str(src)],'hard_wall_seconds':360,'process_started':False,'training_steps':0,'release_mutations':0}
proc=None
try:
    with (D/'stdout').open('xb') as out, (D/'stderr').open('xb') as err:
        proc=subprocess.Popen(report['argv'],stdout=out,stderr=err,start_new_session=True)
        report.update(process_started=True,pid=proc.pid)
        try: rc=proc.wait(timeout=360)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid,signal.SIGKILL); rc=proc.wait(); report['hard_limit_exceeded']=True
        report.update(returncode=rc,status='completed' if rc==0 else 'failed_preserved')
except Exception as e:
    report.update(status='launch_failed',error=repr(e))
finally:
    usage=resource.getrusage(resource.RUSAGE_CHILDREN)
    report.update(complete_child_wall_seconds=time.monotonic()-start,complete_waited_child_and_descendant_CPU_seconds=usage.ru_utime+usage.ru_stime-cpu0.ru_utime-cpu0.ru_stime,child_peak_rss_bytes=usage.ru_maxrss*1024,own_process_CPU_seconds=time.process_time(),finished_utc=datetime.now(timezone.utc).isoformat())
    for name in ['stdout','stderr']:
        if (D/name).exists():
            b=(D/name).read_bytes();report[name]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
    (D/'receipt.json').write_text(json.dumps(report,indent=2,sort_keys=True)+'\n')
    print(json.dumps(report),flush=True)
raise SystemExit(0 if report['status']=='completed' else 2)
